PairedSampleTTest <- function(
    data,
    s1,
    s2,
    a = "0.0250") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("PairedSampleTTest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(s1)) s1 <- jmvcore::resolveQuo(jmvcore::enquo(s1))
    if ( ! missing(s2)) s2 <- jmvcore::resolveQuo(jmvcore::enquo(s2))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(s1), s1, NULL),
            `if`( ! missing(s2), s2, NULL))


    options <- PairedSampleTTestOptions$new(
        s1 = s1,
        s2 = s2,
        a = a)

    analysis <- PairedSampleTTestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

